"""Bounded, read-only point search for JSON families generated by Foundry.

The worker only returns exact rational points.  Rank Hunter's normal plugin
result boundary and evidence pipeline remain responsible for all DB writes and
rank claims.
"""
from __future__ import annotations

import argparse
import json
import os
import sqlite3
import sys
from pathlib import Path

from sage.all import EllipticCurve, QQ

# The adapter launches this file by absolute path. Put the project root on the
# import path explicitly so it works regardless of the launcher's cwd.
PROJECT_ROOT = Path(__file__).resolve().parents[3]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from family_model import FormulaFamily
from rank42.model_points import map_points_exact
from rank42.model_prep import ModelPrepFailure, ModelPrepTimeout, run_global_minimal_model
from rank42.plugin_geometry_result import RESULT_ENV, SCHEMA
from rank42.ratpoints import (
    RatpointsFailure, RatpointsNotFound, RatpointsTimeout,
    probe_version, run_ratpoints,
)
from rank42.search_models import completed_square_polynomial, recover_weierstrass_y


def _stages(value):
    try:
        result = sorted({int(item.strip()) for item in str(value).split(",") if item.strip()})
    except ValueError as exc:
        raise argparse.ArgumentTypeError("stages must be positive comma-separated integers") from exc
    if not result or result[0] <= 0:
        raise argparse.ArgumentTypeError("stages must be positive comma-separated integers")
    return result


def _args(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("--db", required=True)
    parser.add_argument("--mode", choices=("family", "target"), required=True)
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--input")
    source.add_argument("--curve-id", type=int)
    parser.add_argument("--family-file", required=True)
    parser.add_argument("--family-name", required=True)
    parser.add_argument("--plugin-id", required=True)
    parser.add_argument("--stages", type=_stages, default=_stages("1000,10000,100000"))
    parser.add_argument("--timeout", type=int, default=20)
    parser.add_argument("--max-points", type=int, default=32)
    parser.add_argument("--model-prep-timeout", type=int, default=10)
    parser.add_argument("--ratpoints")
    return parser.parse_args(argv)


def _database(path):
    uri = Path(path).resolve().as_uri() + "?mode=ro"
    db = sqlite3.connect(uri, uri=True)
    db.row_factory = sqlite3.Row
    return db


def _subject(args, db):
    if args.mode == "family":
        records = [
            json.loads(line) for line in Path(args.input).read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]
        if not records:
            raise ValueError("candidate file is empty")
        record = records[0]
        candidate_id = int(record["_candidate_id"])
        candidate = db.execute(
            "SELECT curve_id FROM candidates WHERE id=?", (candidate_id,),
        ).fetchone()
        if candidate is None or candidate["curve_id"] is None:
            raise ValueError("selected candidate is not attached to a stored curve")
        curve_id = int(candidate["curve_id"])
        raw_parameter = next(
            (record.get(key) for key in ("native_parameter", "t", "parameter")
             if record.get(key) not in (None, "")),
            None,
        )
    else:
        curve_id = int(args.curve_id)
        raw_parameter = None

    row = db.execute(
        "SELECT family,parameter,a_invariants_json FROM curves WHERE id=?", (curve_id,),
    ).fetchone()
    if row is None or not row["a_invariants_json"]:
        raise ValueError(f"curve #{curve_id} has no stored Weierstrass model")
    curve = EllipticCurve(QQ, [QQ(str(value)) for value in json.loads(row["a_invariants_json"])])
    if curve.discriminant() == 0:
        raise ValueError(f"curve #{curve_id} is singular")
    if raw_parameter is None:
        raw_parameter = row["parameter"]
    parameter = None
    if raw_parameter not in (None, ""):
        try:
            parameter = QQ(str(raw_parameter))
        except (TypeError, ValueError, ZeroDivisionError):
            pass
    return curve_id, parameter, curve, str(row["family"] or "") == args.family_name


def _point_key(point):
    inverse = -point
    return min((str(point[0]), str(point[1])), (str(inverse[0]), str(inverse[1])))


def _append(points, seen, point):
    if point.is_zero():
        return False
    key = _point_key(point)
    if key in seen:
        return False
    seen.add(key)
    points.append(point)
    return True


def _search(curve, *, stages, timeout, model_prep_timeout, ratpoints, max_points):
    try:
        prep = run_global_minimal_model(
            curve.a_invariants(), timeout=max(1, int(model_prep_timeout)),
        )
        minimal = EllipticCurve(QQ, [QQ(str(value)) for value in prep["a_invariants"]])
        to_stored = minimal.isomorphism_to(curve)
        ainvs = list(minimal.a_invariants())
        model_label = "global_minimal"
    except (ModelPrepFailure, ModelPrepTimeout, ArithmeticError, ValueError) as exc:
        minimal = curve
        to_stored = lambda point: curve(point)
        ainvs = list(curve.a_invariants())
        model_label = "stored_model:" + str(exc)[:200]
    try:
        executable = probe_version(ratpoints)["executable"]
    except (RatpointsNotFound, RatpointsTimeout) as exc:
        return [], [{"status": "ratpoints_unavailable", "error": str(exc)[:300]}], model_label

    polynomial = completed_square_polynomial(ainvs)
    points, stage_rows, seen = [], [], set()
    for height in stages:
        if len(points) >= max_points:
            break
        try:
            result = run_ratpoints(
                polynomial, int(height), executable=executable,
                timeout=max(1, int(timeout)),
            )
        except (RatpointsFailure, RatpointsTimeout) as exc:
            stage_rows.append({"stage": height, "status": "timeout_or_error", "error": str(exc)[:300]})
            continue
        added = 0
        for raw in result["points"]:
            if len(points) >= max_points:
                break
            try:
                x, w = QQ(str(raw.x)), QQ(str(raw.y))
                y = QQ(str(recover_weierstrass_y(ainvs, x, w)))
                point = curve(to_stored(minimal(x, y)))
            except Exception:
                continue
            added += int(_append(points, seen, point))
        stage_rows.append({
            "stage": int(height), "status": "completed",
            "new_exact_points": added, "ratpoints_hits": len(result["points"]),
        })
    return points, stage_rows, model_label


def main(argv=None):
    args = _args(argv)
    if args.timeout <= 0 or args.model_prep_timeout < 0 or args.max_points < 0:
        raise SystemExit("timeout must be positive; point limit and model-prep timeout must be nonnegative")
    family_path = Path(args.family_file).resolve()
    family = FormulaFamily.from_json(family_path)
    db = _database(args.db)
    try:
        curve_id, parameter, curve, same_family = _subject(args, db)
    finally:
        db.close()

    points, seen = [], set()
    section_count, section_error = 0, None
    if parameter is not None and (args.mode == "family" or same_family):
        try:
            family_curve = family.curve(parameter)
            sections = family.generic_section_points(parameter)
            if family_curve is None:
                raise ValueError(f"family is singular at parameter {parameter}")
            sections = map_points_exact(family_curve, curve, sections)
            for point in sections:
                section_count += int(_append(points, seen, point))
        except Exception as exc:
            section_error = f"{type(exc).__name__}: {exc}"[:300]

    extras, stages, model = _search(
        curve, stages=args.stages, timeout=args.timeout,
        model_prep_timeout=args.model_prep_timeout, ratpoints=args.ratpoints,
        max_points=args.max_points,
    )
    for point in extras:
        _append(points, seen, point)
    completed_stages = sum(
        1 for item in stages if item.get("status") == "completed"
    )
    failed_stages = len(stages) - completed_stages
    if completed_stages == len(stages) and section_error is None:
        search_status = "completed"
    elif completed_stages or points:
        search_status = "partial"
    else:
        search_status = "inconclusive"
    result = {
        "schema": SCHEMA,
        "status": search_status,
        "engine": "foundry_generated_family_exact_search",
        "engine_version": "0.1.0",
        "algorithm": "exact family sections plus bounded completed-square Ratpoints search",
        "points": [[str(point[0]), str(point[1])] for point in points],
        "artifacts": [],
        "metadata": {
            "plugin_id": args.plugin_id,
            "mode": args.mode,
            "curve_id": curve_id,
            "parameter": str(parameter) if parameter is not None else None,
            "generic_sections_returned": section_count,
            "generic_section_error": section_error,
            "search_model": model,
            "stages": stages,
            "completed_search_stages": completed_stages,
            "failed_search_stages": failed_stages,
            "claim_boundary": "exact points only; Rank Hunter independently certifies specialization rank",
        },
    }
    output = os.environ.get(RESULT_ENV)
    if output:
        Path(output).write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print("FOUNDRY_FAMILY_SEARCH_RESULT=" + json.dumps({
        "plugin_id": args.plugin_id, "curve_id": curve_id,
        "parameter": str(parameter) if parameter is not None else None,
        "points": len(points), "generic_sections": section_count,
        "section_error": section_error, "status": search_status,
    }, sort_keys=True), flush=True)


if __name__ == "__main__":
    main()
